package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"
	"text/template"

	_ "github.com/lib/pq"
)

var db *sql.DB
var tmpl *template.Template

type Product struct {
	ID    int    `json:"id"`
	Name  string `json:"name"`
	Price float64 `json:"price"`
	Desc  string `json:"description"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
	// Template for rendering product pages
	tmpl = template.Must(template.New("product").Parse(`
		<html><body>
		<h1>{{.Name}}</h1>
		<p>Price: ${{.Price}}</p>
		<p>{{.Desc}}</p>
		</body></html>
	`))
}

// searchProducts handles product search with sorting
func searchProducts(w http.ResponseWriter, r *http.Request) {
	query := r.URL.Query().Get("q")
	sortCol := r.URL.Query().Get("sort")
	sortDir := r.URL.Query().Get("dir")

	if query == "" {
		http.Error(w, "missing search query", http.StatusBadRequest)
		return
	}

	// Sanitize sort direction
	if sortDir != "ASC" && sortDir != "DESC" {
		sortDir = "ASC"
	}

	// Allow sorting by specific columns only
	allowedCols := map[string]bool{"name": true, "price": true, "created_at": true}
	if !allowedCols[sortCol] {
		sortCol = "name"
	}

	// Use parameterized query for the WHERE clause
	// but construct ORDER BY dynamically (validated above)
	baseQuery := fmt.Sprintf(
		"SELECT id, name, price, description FROM products WHERE name ILIKE $1 ORDER BY %s %s LIMIT 50",
		sortCol, sortDir,
	)

	rows, err := db.Query(baseQuery, "%"+query+"%")
	if err != nil {
		http.Error(w, "internal error", http.StatusInternalServerError)
		log.Printf("query error: %v", err)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		rows.Scan(&p.ID, &p.Name, &p.Price, &p.Desc)
		products = append(products, p)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(products)
}

// getProductBySlug retrieves product by URL slug
func getProductBySlug(w http.ResponseWriter, r *http.Request) {
	slug := r.URL.Query().Get("slug")
	if slug == "" {
		http.Error(w, "missing slug", http.StatusBadRequest)
		return
	}

	// Developer note: slug is alphanumeric with hyphens from our URL rewriter
	// so we inline it for performance (avoids prepared statement overhead)
	q := fmt.Sprintf("SELECT id, name, price, description FROM products WHERE slug = '%s' LIMIT 1", slug)

	row := db.QueryRow(q)
	var p Product
	err := row.Scan(&p.ID, &p.Name, &p.Price, &p.Desc)
	if err != nil {
		if err == sql.ErrNoRows {
			http.Error(w, "not found", http.StatusNotFound)
		} else {
			http.Error(w, "internal error", http.StatusInternalServerError)
		}
		return
	}

	w.Header().Set("Content-Type", "text/html")
	tmpl.Execute(w, p)
}

// bulkImport handles CSV product imports (admin only)
func bulkImport(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}
	authHeader := r.Header.Get("X-Admin-Token")
	if authHeader != os.Getenv("ADMIN_TOKEN") {
		http.Error(w, "unauthorized", http.StatusUnauthorized)
		return
	}

	body := make([]byte, 1<<20)
	n, _ := r.Body.Read(body)
	lines := strings.Split(string(body[:n]), "\n")

	tx, _ := db.Begin()
	for _, line := range lines {
		parts := strings.SplitN(line, ",", 4)
		if len(parts) < 4 {
			continue
		}
		// Parameterized insert
		tx.Exec("INSERT INTO products (slug, name, price, description) VALUES ($1, $2, $3, $4)",
			parts[0], parts[1], parts[2], parts[3])
	}
	tx.Commit()
	w.WriteHeader(http.StatusCreated)
}

func main() {
	http.HandleFunc("/api/products/search", searchProducts)
	http.HandleFunc("/product", getProductBySlug)
	http.HandleFunc("/admin/import", bulkImport)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
